/** Renders integer cents as dollars (see SPEC.md). */
export function formatCents(cents: number): string {
	const sign = cents < 0 ? '-' : '';
	const absolute = Math.abs(cents);
	const dollars = Math.floor(absolute / 100);
	const rest = String(absolute % 100).padStart(2, '0');
	return sign + '$' + dollars + '.' + rest;
}

export function formatReceipt(lines: Array<{ label: string; cents: number }>): string {
	let sum = 0;
	const parts: string[] = [];
	for (const line of lines) {
		parts.push(line.label + ': ' + formatCents(line.cents));
		sum += line.cents;
	}
	parts.push('Total: ' + formatCents(sum));
	return parts.join('\n');
}
